<td><span class="status <?=Security::e($c['status'])?>"><?=Security::e($statuses[$c['status']]??$c['status'])?></span></td><td><?=Security::e((string)$c['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></section>
